(assert (= "1.12.6" (clojure-version)))
(prn (binding [*math-context* :invalid] (try (eval '(+ 1 2)) (catch Throwable e :error))))
(prn (binding [*math-context* :invalid] (try (eval '(quote :ok)) (catch Throwable e :error))))
(prn (binding [*math-context* {:precision 3}] (try (eval '(let [x 20] (+ x 22))) (catch Throwable e :error))))
(prn (binding [*math-context* :invalid] (try (eval '*math-context*) (catch Throwable e :error))))
