(prn (do (def invalid-context-effects (atom [])) (let [result (binding [*math-context* :invalid] (try (eval '(do (swap! invalid-context-effects conj :before) (/ 1M 3M) (swap! invalid-context-effects conj :after))) (catch Throwable e :error)))] [result @invalid-context-effects])))
(prn (do (eval '(defmacro invalid-context-read [] (list 'quote *math-context*))) (binding [*math-context* :invalid] (try (eval '(invalid-context-read)) (catch Throwable e :error)))))
