(prn (do (eval '(defmacro invalid-context-decimal [] (/ 1M 3M))) [(binding [*math-context* :invalid] (try (eval '(invalid-context-decimal)) (catch Throwable e :error))) (with-precision 3 (eval '(invalid-context-decimal))) *math-context*]))
