(prn (binding [*math-context* {:bad (fn [] :invalid)}] (try (eval '(quote :ok)) (catch Throwable e :error))))
(prn (let [v (eval '(defmacro invalid-context-opaque-decimal [] (let [effects (atom []) result (try (do (swap! effects conj :before) (/ 1M 3M) (swap! effects conj :after)) (catch Throwable e :error))] [result @effects])))] (binding [*math-context* (fn [] :invalid)] (try (v nil nil) (catch Throwable e :error)))))
(prn (do (eval '(defmacro invalid-context-safe [] (list 'quote :safe))) (let [effects (atom 0) context (lazy-seq (swap! effects inc) (list :invalid))] (binding [*math-context* context] [(try (eval '(invalid-context-safe)) (catch Throwable e :error)) @effects]))))
(prn (let [v (eval '(defmacro context-override-raw [] (with-precision 3 (/ 1M 3M))))] (binding [*math-context* (fn [] :invalid)] (try (v nil nil) (catch Throwable e :error)))))
