(prn (let [v (eval '(defmacro context-override-error [] (binding [*math-context* nil] (throw (ex-info "inside override" {:inside true})))))] (binding [*math-context* (fn [] :invalid)] (try (v nil nil) (catch Throwable e (ex-data e))))))
